import fs from "node:fs";import os from "node:os";import path from "node:path";import {execFileSync} from "node:child_process";const dir=fs.mkdtempSync(path.join(os.tmpdir(),"gp9-")),src=path.join(dir,"in.json");fs.writeFileSync(src,JSON.stringify({profiles:[{authUid:"a",playerId:"p_a",preferences:{favoritePuzzleTypes:["bin"],dailyDifficulty:{bin:"normal"}}},{authUid:"b",playerId:"p_b",preferences:{tutorials:{bin:"completed"}}}]}));const run=()=>execFileSync(process.execPath,["scripts/migrate-phase9.mjs",src,"--apply"],{encoding:"utf8"});run();const out=JSON.parse(fs.readFileSync(path.join(dir,"in-phase9.json"),"utf8"));if(out.profiles[0].preferences.tutorials.bin!=="skipped")throw new Error("legacy default ontbreekt");if(out.profiles[1].preferences.tutorials.bin!=="completed")throw new Error("bestaande status overschreven");const once=fs.readFileSync(path.join(dir,"in-phase9.json"),"utf8");run();const twice=fs.readFileSync(path.join(dir,"in-phase9.json"),"utf8");if(once!==twice)throw new Error("migratie niet deterministisch");console.log("Fase 9 migratie: OK");

const obj=path.join(dir,"object.json");fs.writeFileSync(obj,JSON.stringify({profiles:{a:{playerId:"p_a"}}}));execFileSync(process.execPath,["scripts/migrate-phase9.mjs",obj,"--apply"],{encoding:"utf8"});const objectOut=JSON.parse(fs.readFileSync(path.join(dir,"object-phase9.json"),"utf8"));if(objectOut.profiles.a.preferences.tutorials.bin!=="skipped")throw new Error("object-vorm productie-export niet ondersteund");
